INSERT INTO emc_lot_genealogy (id, input_lot_id, output_lot_id, response_id, quantity) SELECT gen_random_uuid(), ma.lot_id, ?, ma.response_id, ma.quantity FROM emc_material_actual ma WHERE ma.response_id = ? AND ma.material_use = 'CONSUMED' AND ma.lot_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM emc_lot_genealogy g WHERE g.input_lot_id = ma.lot_id AND g.output_lot_id = ? AND g.response_id = ma.response_id)
